-- create-table OTTO_SHOPS
CREATE TABLE "OTTO_SHOPS" (
  "/RT/TENANT" VARCHAR(16) NOT NULL,
  "SHOP_ID" VARCHAR(12) NOT NULL,
  "COMPANY_ID" VARCHAR(10) NOT NULL,
  "NAME" VARCHAR(80) NOT NULL,
  CONSTRAINT "OTTO_SHOPS#PK" PRIMARY KEY ("/RT/TENANT", "SHOP_ID"),
  CONSTRAINT "OTTO_SHOPS#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "OTTO_SHOPS#FK#COMPANY" FOREIGN KEY ("/RT/TENANT", "COMPANY_ID") REFERENCES "COMPANIES" ("/RT/TENANT", "COMPANY_ID") DEFERRABLE INITIALLY IMMEDIATE
);

-- alter-type COMPANIES./TROTTO/OTTO_ID (CHAR(20) -> CHAR(32))
ALTER TABLE "COMPANIES" ALTER COLUMN "/TROTTO/OTTO_ID" TYPE VARCHAR(32);

-- add-column COMPANIES./TROTTO/ACTIVE (BOOL)
ALTER TABLE "COMPANIES" ADD COLUMN "/TROTTO/ACTIVE" BOOLEAN NOT NULL DEFAULT FALSE;

-- add-column COMPANIES./TROTTO/MAIN_SHOP (CHAR(12))
ALTER TABLE "COMPANIES" ADD COLUMN "/TROTTO/MAIN_SHOP" VARCHAR(12);

-- add-foreign-key COMPANIES./TROTTO/MAIN_SHOP (references OTTO_SHOPS)
ALTER TABLE "COMPANIES" ADD CONSTRAINT "COMPANIES#FK#/TROTTO/MAIN_SHOP" FOREIGN KEY ("/RT/TENANT", "/TROTTO/MAIN_SHOP") REFERENCES "OTTO_SHOPS" ("/RT/TENANT", "SHOP_ID") DEFERRABLE INITIALLY IMMEDIATE;

